// Pure mapping: resin plot/hline styles → lightweight-charts series choices.
// No chart objects here — everything in map/ is unit-testable without a canvas.
import { LineStyle, LineType } from "lightweight-charts";
// Pine's ten plot styles against LWC's series vocabulary. The right column of
// the support matrix in the README is generated from `approximated` here —
// keep the two in sync.
const PLOT_STYLE_CHOICES = {
    line: { kind: "line", approximated: false },
    linebr: { kind: "line", approximated: true }, // LWC lines bridge gaps we render as whitespace
    stepline: { kind: "line", lineType: LineType.WithSteps, approximated: false },
    stepline_diamond: { kind: "line", lineType: LineType.WithSteps, approximated: true }, // diamonds dropped
    histogram: { kind: "histogram", approximated: false },
    columns: { kind: "histogram", approximated: false },
    area: { kind: "area", approximated: false },
    areabr: { kind: "area", approximated: true },
    cross: { kind: "line", approximated: true }, // marker-per-point styles fall back to a line
    circles: { kind: "line", approximated: true },
};
export function plotSeriesChoice(style) {
    return PLOT_STYLE_CHOICES[style] ?? { kind: "line", approximated: true };
}
const HLINE_STYLES = {
    solid: LineStyle.Solid,
    dotted: LineStyle.Dotted,
    dashed: LineStyle.Dashed,
};
export function hlineLineStyle(style) {
    return HLINE_STYLES[style] ?? LineStyle.Solid;
}
